// Serialized GLB/clip correctness gate against ufbx scene evaluation, using read-only sources.
#define wmain parser_wmain
#define main parser_main
#include "../src/main.cpp"
#undef wmain
#undef main
static ufbx_vec3 v3(const J& a){return {a[0].get<double>(),a[1].get<double>(),a[2].get<double>()};}
static ufbx_quat q4(const J& a){return {a[0].get<double>(),a[1].get<double>(),a[2].get<double>(),a[3].get<double>()};}
static ufbx_transform transform(const J& n){return {v3(n.at("translation")),q4(n.at("rotation")),v3(n.at("scale"))};}
static double delta(ufbx_matrix a,ufbx_matrix b){double d=0;for(int c=0;c<4;c++)for(int r=0;r<3;r++)d=std::max(d,std::abs(a.cols[c].v[r]-b.cols[c].v[r]));return d;}
static std::vector<ufbx_matrix> worlds(const std::vector<ufbx_transform>& t,ufbx_scene* s){std::vector<ufbx_matrix> out(t.size());std::vector<bool> done(t.size());std::function<void(size_t)> solve=[&](size_t i){if(done[i])return;auto* n=s->nodes.data[i];auto local=ufbx_transform_to_matrix(&t[i]);if(n->parent){size_t p=n->parent->typed_id;solve(p);out[i]=ufbx_matrix_mul(&out[p],&local);}else out[i]=local;done[i]=true;};for(size_t i=0;i<t.size();i++)solve(i);return out;}
static J readClipBinary(const fs::path& path){std::ifstream f(path,std::ios::binary);std::vector<uint8_t> raw((std::istreambuf_iterator<char>(f)),{});if(raw.size()<16||std::memcmp(raw.data(),"BFCLIP1\0",8))throw Failure("INVALID_CLIP","Invalid binary clip");uint32_t jsonBytes,dataBytes;std::memcpy(&jsonBytes,raw.data()+8,4);std::memcpy(&dataBytes,raw.data()+12,4);size_t body=16+((size_t)jsonBytes+7)/8*8;if(body>raw.size()||dataBytes%8||body+dataBytes!=raw.size())throw Failure("INVALID_CLIP","Invalid binary clip bounds");J clip=J::parse(std::string((char*)raw.data()+16,jsonBytes));for(auto& track:clip["tracks"])for(const char* field:{"times","values"}){size_t offset=track[field].at("offset"),count=track[field].at("count");if(offset>dataBytes/8||count>dataBytes/8-offset)throw Failure("INVALID_CLIP","Invalid binary clip range");J values=J::array();for(size_t i=0;i<count;i++){double value;std::memcpy(&value,raw.data()+body+(offset+i)*8,8);values.push_back(value);}track[field]=std::move(values);}return clip;}
static void applyTrack(ufbx_transform& t,const J& tr,double time){auto& times=tr.at("times");auto& vals=tr.at("values");std::string p=tr.at("property");size_t lanes=p=="rotation"?4:3,hi=0;while(hi+1<times.size()&&times[hi].get<double>()<time)hi++;size_t lo=hi?hi-1:0;double a=times[lo],b=times[hi],mix=b>a?(time-a)/(b-a):0;mix=std::max(0.0,std::min(1.0,mix));if(p=="rotation"){ufbx_quat q0{},q1{};for(size_t k=0;k<4;k++){q0.v[k]=vals[lo*lanes+k];q1.v[k]=vals[hi*lanes+k];}t.rotation=ufbx_quat_slerp(q0,q1,mix);}else{ufbx_vec3 v{};for(size_t k=0;k<3;k++)v.v[k]=vals[lo*lanes+k].get<double>()*(1-mix)+vals[hi*lanes+k].get<double>()*mix;if(p=="translation")t.translation=v;else t.scale=v;}}
struct SerializedVertex {ufbx_vec3 position;std::array<uint32_t,4> joints;std::array<double,4> weights;size_t skin;};
static std::vector<double> readAccessor(const J& glb,const std::vector<uint8_t>& bin,size_t index){auto ac=glb["accessors"][index];auto view=glb["bufferViews"][ac["bufferView"].get<size_t>()];std::string type=ac["type"];size_t lanes=type=="MAT4"?16:type=="VEC4"?4:type=="VEC3"?3:type=="VEC2"?2:1;size_t count=ac["count"].get<size_t>()*lanes;size_t offset=view.value("byteOffset",(size_t)0)+ac.value("byteOffset",(size_t)0);int component=ac["componentType"];size_t width=component==5123?2:4;if(offset+count*width>bin.size())throw Failure("INVALID_GLB","Accessor outside binary chunk");std::vector<double> out;out.reserve(count);for(size_t i=0;i<count;i++){const uint8_t* p=bin.data()+offset+i*width;if(component==5126){float value;std::memcpy(&value,p,4);out.push_back(value);}else if(component==5123){uint16_t value;std::memcpy(&value,p,2);out.push_back(value);}else throw Failure("INVALID_GLB","Unexpected accessor component");}return out;}
static int verify(const std::vector<std::string>& args){if(args.size()<5)throw Failure("USAGE","verify-real base.fbx action1.fbx action2.fbx output-dir");fs::path out=fs::u8path(args[4]);fs::create_directories(out);Context base({{"source",args[1]}});auto modelResult=model(base,out/"base.glb");std::ifstream f(out/"base.glb",std::ios::binary);uint32_t header[5];f.read((char*)header,sizeof(header));std::string json(header[3],' ');f.read(json.data(),json.size());J glb=J::parse(json);uint32_t binHeader[2];f.read((char*)binHeader,8);if(binHeader[1]!=0x004e4942)throw Failure("INVALID_GLB","Missing binary chunk");std::vector<uint8_t> binary(binHeader[0]);f.read((char*)binary.data(),binary.size());
 std::set<std::array<float,3>> samplePositions;for(auto* mesh:base.scene->meshes)for(size_t vi=0;vi<mesh->vertices.count;vi+=std::max((size_t)1,mesh->vertices.count/100)){auto v=mesh->vertices.data[vi];samplePositions.insert({(float)v.x,(float)v.y,(float)v.z});}
 std::vector<std::vector<ufbx_matrix>> serializedInverse;for(auto& sk:glb["skins"]){auto values=readAccessor(glb,binary,sk["inverseBindMatrices"]);std::vector<ufbx_matrix> matrices;for(size_t i=0;i<values.size();i+=16){ufbx_matrix m{};for(size_t col=0;col<4;col++)for(size_t row=0;row<3;row++)m.cols[col].v[row]=values[i+col*4+row];matrices.push_back(m);}serializedInverse.push_back(matrices);}
 std::map<std::array<float,3>,std::vector<SerializedVertex>> emitted;
 for(auto& node:glb["nodes"]){if(!node.contains("mesh")||!node.contains("skin"))continue;size_t skin=node["skin"];for(auto& prim:glb["meshes"][node["mesh"].get<size_t>()]["primitives"]){auto attrs=prim["attributes"];auto positions=readAccessor(glb,binary,attrs["POSITION"]);auto joints=readAccessor(glb,binary,attrs["JOINTS_0"]);auto weights=readAccessor(glb,binary,attrs["WEIGHTS_0"]);for(size_t vi=0;vi<positions.size()/3;vi++){std::array<float,3> key={(float)positions[vi*3],(float)positions[vi*3+1],(float)positions[vi*3+2]};if(!samplePositions.count(key))continue;SerializedVertex v{};v.position={positions[vi*3],positions[vi*3+1],positions[vi*3+2]};v.skin=skin;for(size_t k=0;k<4;k++){v.joints[k]=(uint32_t)joints[vi*4+k];v.weights[k]=weights[vi*4+k];}emitted[key].push_back(v);}}}
 std::vector<ufbx_transform> defaults;double baseError=0;for(auto& n:glb["nodes"])defaults.push_back(transform(n));auto baseWorld=worlds(defaults,base.scene.get());for(auto* n:base.scene->nodes)baseError=std::max(baseError,delta(baseWorld[n->typed_id],n->node_to_world));J actions=J::array();
 for(size_t ai=2;ai<=3;ai++){Context action({{"source",args[ai]}});auto result=clip(action,0,out/("action"+std::to_string(ai-1)+".clipb"));J parsed=readClipBinary(out/("action"+std::to_string(ai-1)+".clipb"));std::map<std::string,size_t> ids;std::map<std::string,const ufbx_node*> paths;for(auto* n:base.scene->nodes)paths[nodePath(n)]=n;for(auto* n:action.scene->nodes){auto it=paths.find(nodePath(n));if(it!=paths.end())ids[id(n)]=it->second->typed_id;}
 double worst=0,vertexWorst=0;size_t checks=0,vertexChecks=0;double duration=parsed["duration"];J times=J::array();for(double fraction:{0.0,0.173,0.5,0.837,1.0}){double time=fraction*duration;auto pose=defaults;for(auto& tr:parsed["tracks"]){auto it=ids.find(tr["nodeId"]);if(it!=ids.end())applyTrack(pose[it->second],tr,time);}auto actual=worlds(pose,base.scene.get());ufbx_error e{};Scene evaluated(ufbx_evaluate_scene(action.scene.get(),action.scene->anim_stacks.data[0]->anim,time+action.scene->anim_stacks.data[0]->time_begin,nullptr,&e),ufbx_free_scene);if(!evaluated)throw Failure("EVALUATION_FAILED","Native scene evaluation failed");std::map<std::string,ufbx_matrix> native;for(auto* n:evaluated->nodes)native[nodePath(n)]=n->node_to_world;double frameWorst=0;for(auto* n:base.scene->nodes){if(!n->bone)continue;auto it=native.find(nodePath(n));if(it==native.end())throw Failure("MISSING_NODE","No action node for base joint");double d=delta(actual[n->typed_id],it->second);frameWorst=std::max(frameWorst,d);checks++;}
 for(auto* mesh:base.scene->meshes){if(!mesh->skin_deformers.count)continue;auto* skin=mesh->skin_deformers.data[0];for(size_t vi=0;vi<mesh->vertices.count;vi+=std::max((size_t)1,mesh->vertices.count/100)){auto sv=skin->vertices.data[vi];ufbx_vec3 expected{};double sum=0;for(size_t w=0;w<sv.num_weights;w++){auto sw=skin->weights.data[sv.weight_begin+w];auto* cl=skin->clusters.data[sw.cluster_index];auto nw=native.at(nodePath(cl->bone_node));auto bm=ufbx_matrix_mul(&nw,&cl->geometry_to_bone);auto bp=ufbx_transform_position(&bm,mesh->vertices.data[vi]);for(int k=0;k<3;k++)expected.v[k]+=bp.v[k]*sw.weight;sum+=sw.weight;}
 auto p=mesh->vertices.data[vi];std::array<float,3> key={(float)p.x,(float)p.y,(float)p.z};auto found=emitted.find(key);if(found==emitted.end())throw Failure("MISSING_SERIALIZED_VERTEX","Sample source vertex missing from emitted GLB");
 for(auto& vertex:found->second){ufbx_vec3 actualPosition{};auto& sk=glb["skins"][vertex.skin];for(size_t k=0;k<4;k++){size_t ji=vertex.joints[k];size_t nodeIndex=sk["joints"][ji];auto mat=ufbx_matrix_mul(&actual[nodeIndex],&serializedInverse[vertex.skin][ji]);auto pos=ufbx_transform_position(&mat,vertex.position);for(int lane=0;lane<3;lane++)actualPosition.v[lane]+=pos.v[lane]*vertex.weights[k];}for(int lane=0;lane<3;lane++)vertexWorst=std::max(vertexWorst,std::abs(actualPosition.v[lane]-expected.v[lane]/sum));vertexChecks++;}
 }}
 worst=std::max(worst,frameWorst);times.push_back({{"time",time},{"maxWorldMatrixError",frameWorst}});}
 actions.push_back({{"source",args[ai]},{"duration",duration},{"fps",parsed["fps"]},{"trackCount",parsed["tracks"].size()},{"jointMatrixChecks",checks},{"maxWorldMatrixError",worst},{"skinnedVertexChecks",vertexChecks},{"maxSkinnedVertexErrorMeters",vertexWorst},{"times",times}});
 }
 bool ok=baseError<1e-8;for(auto& a:actions)ok=ok&&a["maxWorldMatrixError"].get<double>()<0.02&&a["maxSkinnedVertexErrorMeters"].get<double>()<0.005;J report={{"ok",ok},{"parserVersion",VERSION},{"baseSource",args[1]},{"baseNodeCount",defaults.size()},{"baseMaxWorldMatrixError",baseError},{"actions",actions},{"method","Read actual GLB POSITION/JOINTS/WEIGHTS/inverseBind binary buffers and serialized clip; rebuild hierarchy and skin; compare native ufbx vertices/weights/bind evaluated at 5 timestamps including off-key times; check every emitted duplicate of sampled source positions"}};writeJson(out/"correctness.json",report);std::cout<<report.dump(2)<<'\n';return ok?0:1;
}
#ifdef _WIN32
int wmain(int argc,wchar_t** argv){try{std::vector<std::string> args;for(int i=0;i<argc;i++)args.push_back(fs::path(argv[i]).u8string());return verify(args);}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
#else
int main(int argc,char** argv){try{return verify(std::vector<std::string>(argv,argv+argc));}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
#endif
